CREATE TABLE public.contact_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), full_name text NOT NULL CHECK (length(full_name) BETWEEN 1 AND 100), email text NOT NULL CHECK(length(email) <= 255), phone text NOT NULL DEFAULT '' CHECK(length(phone) <= 40), country text NOT NULL CHECK(length(country) BETWEEN 1 AND 100), organisation text NOT NULL DEFAULT '' CHECK(length(organisation) <= 200), subject text NOT NULL CHECK(subject IN ('general','partnership','membership','media','training','other')), message text NOT NULL CHECK(length(message) BETWEEN 20 AND 5000), preferred_language text NOT NULL CHECK(preferred_language IN ('en','fr')), consent boolean NOT NULL CHECK(consent), status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','read','replied')));
GRANT SELECT, UPDATE ON public.contact_messages TO authenticated;
GRANT ALL ON public.contact_messages TO service_role;
ALTER TABLE public.contact_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admins read messages" ON public.contact_messages FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admins update messages" ON public.contact_messages FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.newsletter_subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), email text UNIQUE NOT NULL CHECK(length(email) <= 255), language text NOT NULL DEFAULT 'en' CHECK(language IN ('en','fr')));
GRANT SELECT ON public.newsletter_subscriptions TO authenticated;
GRANT ALL ON public.newsletter_subscriptions TO service_role;
ALTER TABLE public.newsletter_subscriptions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admins read subscriptions" ON public.newsletter_subscriptions FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.regional_contacts (id text PRIMARY KEY, name text NOT NULL DEFAULT '[Name]' CHECK(length(name) <= 100), email text NOT NULL DEFAULT '[Email TBC]' CHECK(length(email) <= 255), is_placeholder boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.regional_contacts TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.regional_contacts TO authenticated;
GRANT ALL ON public.regional_contacts TO service_role;
ALTER TABLE public.regional_contacts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public read focal points" ON public.regional_contacts FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "Admins manage focal points" ON public.regional_contacts FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
ALTER TABLE public.site_settings ADD COLUMN secretariat_email text NOT NULL DEFAULT 'secretariatexecutif.iapa@gmail.com', ADD COLUMN hq_address text NOT NULL DEFAULT 'The Rombus, Plot 24, Tumu Street, Accra, Ghana', ADD COLUMN contact_phones text NOT NULL DEFAULT '+237 67501 1100 · +226 66 59 77 77', ADD COLUMN whatsapp text NOT NULL DEFAULT '', ADD COLUMN office_hours text NOT NULL DEFAULT '', ADD COLUMN hq_coordinates text NOT NULL DEFAULT '';